"""Regla nueva para CPMP: prioriza mover contenedores a pilas ya ordenadas
cuando el movimiento mantiene o mejora la estructura y evita caer al comodín."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any
import importlib

from core.machine import FALLBACK
from core.rules import RuleMachine, NoTransitions


def _resolve_move_class():
    candidates = (
        "cpmp",
        "problem",
        "problems.cpmp",
        "problems.cpmp.view",
        "core.views.cpmp",
        "core.problem",
    )
    for mod_name in candidates:
        try:
            mod = importlib.import_module(mod_name)
        except ImportError:
            continue
        move_cls = getattr(mod, "Move", None)
        if move_cls is not None:
            return move_cls
    raise ImportError("No se pudo resolver la clase Move del problema CPMP")


Move = _resolve_move_class()


COMPONENT = {
    "name": "place_on_sorted_stack",
    "slot": "construction_machine",
    "compatible_skeletons": ["CONSTRUCT"],
    "requires": [],
    "params": {
        "source_bad_weight": {"type": "float", "range": [0.0, 10.0], "default": 3.0},
        "source_ub_weight": {"type": "float", "range": [0.0, 10.0], "default": 2.0},
        "fit_weight": {"type": "float", "range": [0.0, 10.0], "default": 4.0},
        "slack_weight": {"type": "float", "range": [0.0, 10.0], "default": 1.0},
    },
}


@dataclass(frozen=True)
class _RuleMemory:
    pass


class PlaceOnSortedStackRule:
    name = "place_on_sorted_stack"

    def __init__(
        self,
        problem,
        source_bad_weight: float = 3.0,
        source_ub_weight: float = 2.0,
        fit_weight: float = 4.0,
        slack_weight: float = 1.0,
    ) -> None:
        self.problem = problem
        self.source_bad_weight = source_bad_weight
        self.source_ub_weight = source_ub_weight
        self.fit_weight = fit_weight
        self.slack_weight = slack_weight

    def init(self, partial):
        return _RuleMemory()

    def start(self, partial, memory):
        return memory

    def update(self, partial, memory, action):
        return memory

    def done(self, partial, memory) -> bool:
        return True

    def propose(self, partial, memory):
        candidates = []
        for so in range(partial.S):
            if not partial.stacks[so]:
                continue
            c = partial.g(so)
            source_bad = partial.bad()
            source_ub = partial.ub(so)

            for sd in range(partial.S):
                if so == sd or len(partial.stacks[sd]) >= partial.H:
                    continue
                if len(partial.stacks[sd]) == 0:
                    continue
                if partial.g(sd) < c:
                    continue

                dest_top = partial.g(sd)
                slack = dest_top - c
                fit = 1.0 / (1.0 + float(slack))

                score = (
                    self.source_bad_weight * float(source_bad)
                    + self.source_ub_weight * float(source_ub)
                    - self.fit_weight * fit
                    + self.slack_weight * float(slack)
                )
                candidates.append((score, Move(so=so, sd=sd)))

        candidates.sort(key=lambda t: (t[0], t[1].so, t[1].sd))
        return [a for _, a in candidates]


class _Transitions:
    def __init__(self):
        self._memory = ()

    def initial(self, partial):
        return ()

    def select(self, partial, memory, rules):
        if rules.applies("place_on_sorted_stack"):
            return "place_on_sorted_stack", ()
        return FALLBACK, ()


def build_component(problem, **params):
    source_bad_weight = params.get("source_bad_weight", COMPONENT["params"]["source_bad_weight"]["default"])
    source_ub_weight = params.get("source_ub_weight", COMPONENT["params"]["source_ub_weight"]["default"])
    fit_weight = params.get("fit_weight", COMPONENT["params"]["fit_weight"]["default"])
    slack_weight = params.get("slack_weight", COMPONENT["params"]["slack_weight"]["default"])

    rule = PlaceOnSortedStackRule(
        problem,
        source_bad_weight=source_bad_weight,
        source_ub_weight=source_ub_weight,
        fit_weight=fit_weight,
        slack_weight=slack_weight,
    )
    return RuleMachine(problem, [rule], _Transitions())
